{
  "version": 1,
  "cases": [
    {
      "id": "basic_example",
      "purpose": "Draw six numbers between 1 and 10 with seed 7",
      "function": "random_number_draw",
      "kwargs": {
        "count": 6,
        "lower_bound": 1,
        "upper_bound": 10,
        "seed": 7
      },
      "expect": {
        "kind": "value",
        "value": [
          8,
          9,
          2,
          4,
          4,
          3
        ]
      }
    },
    {
      "id": "zero_count",
      "purpose": "Test zero count case",
      "function": "random_number_draw",
      "kwargs": {
        "count": 0,
        "lower_bound": 1,
        "upper_bound": 10,
        "seed": 7
      },
      "expect": {
        "kind": "value",
        "value": []
      }
    },
    {
      "id": "equal_bounds",
      "purpose": "Test equal bounds",
      "function": "random_number_draw",
      "kwargs": {
        "count": 3,
        "lower_bound": 5,
        "upper_bound": 5,
        "seed": 7
      },
      "expect": {
        "kind": "value",
        "value": [
          5,
          5,
          5
        ]
      }
    },
    {
      "id": "invalid_count_type",
      "purpose": "Test invalid count type (string)",
      "function": "random_number_draw",
      "kwargs": {
        "count": "5",
        "lower_bound": 1,
        "upper_bound": 10,
        "seed": 7
      },
      "expect": {
        "kind": "raises",
        "type": "TypeError"
      }
    },
    {
      "id": "invalid_bounds_order",
      "purpose": "Test invalid bounds order",
      "function": "random_number_draw",
      "kwargs": {
        "count": 5,
        "lower_bound": 10,
        "upper_bound": 1,
        "seed": 7
      },
      "expect": {
        "kind": "raises",
        "type": "ValueError"
      }
    }
  ]
}
